quiz.answer:
package main

import (
	"encoding/base64"
	"fmt"
)

func main() {
	var s string
	fmt.Scan(&s)
	data, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		fmt.Println("decode error")
		return
	}
	fmt.Println(string(data))
}

