package main

import "fmt"

func main() {
	var now, exp int64
	fmt.Scan(&now, &exp)
	// now が exp を過ぎていれば token expired、そうでなければ valid を出力する
}

quiz.answer:
package main

import "fmt"

func main() {
	var now, exp int64
	fmt.Scan(&now, &exp)
	if now > exp {
		fmt.Println("token expired")
		return
	}
	fmt.Println("valid")
}
